const compare = $input.first().json;
const ctx = $('Normalize Per Push').item.json;
const files = Array.isArray(compare.files) ? compare.files : [];
const commitCount = Array.isArray(compare.commits) ? compare.commits.length : 0;
const patches = files.slice(0, 40).map((file) => {
  const patch = file.patch || '[No textual patch available]';
  return `FILE: ${file.filename}
STATUS: ${file.status || 'modified'}
ADDITIONS: ${file.additions || 0}
DELETIONS: ${file.deletions || 0}
PATCH:
${patch}`;
}).join('

');

const prompt = `You are a precise technical audit assistant for a hackathon system. Analyze the changes of this code push and return EXACTLY a valid JSON response. Do not wrap the JSON in markdown code blocks, and do not provide any explanation outside of the JSON.

You must return the following JSON keys:
- reviewKind: "PER_PUSH_TECHNICAL_AUDIT"
- status: "DONE"
- isScoreBased: false
- isFinalDecision: false
- overallPicture: { pushSummary, significantChange: boolean, changeImpactLevel, mainAffectedAreas }
- techStackDetected: { frontend: array string, backend: array string, database: array string, ai: array string, retrieval: array string, testing: array string }
- technicalFindings: array of objects { type, severity, title, evidence: array string, comment, recommendedAction }
- rubricAwareComments: array
- suggestedTestCases: array { title, purpose, expectedObservation }
- suggestedJudgeQuestions: array string
- costControlNotes: { llmCallReason, skippedFiles: array string, tokenSavingStrategy: array string }
- historicalSynthesis: null
- currentTechnicalSnapshot: null
- riskSummary: array of objects { severity, title, summary }
- judgeDashboardSummary: { headline, needsHumanReview, primaryConcerns: array string, recommendedJudgeFocus: array string }
- needsHumanReview: boolean

Important Constraints:
- significantChange MUST be a boolean (true or false).
- Valid values for changeImpactLevel: "LOW", "MEDIUM", "HIGH", "CRITICAL", "UNKNOWN"
- Valid values for severity: "LOW", "MEDIUM", "HIGH", "CRITICAL"
- Valid values for technicalFindings.type: "ARCHITECTURE", "SECURITY", "RELIABILITY", "PERFORMANCE", "TESTING", "AI_USAGE", "RAG", "AGENT", "DEPENDENCY", "MAINTAINABILITY"

Context Information:
- Repository: ${ctx.repositoryFullName}
- Branch: ${ctx.branch}
- Before SHA: ${ctx.beforeCommitSha}
- After SHA: ${ctx.afterCommitSha}
- Number of commits in compare: ${commitCount}
- Number of changed files: ${files.length}

Diff Patch Content:
${patches || '[No patch text available to analyze]'}

If there is insufficient evidence, you must still return a valid JSON structure with empty lists or default values from the allowed sets. Do not give any scores or make final decisions.

Note: All descriptive text outputs (such as pushSummary, comment, recommendedAction, title, summary, headline, primaryConcerns, and recommendedJudgeFocus) must be written in Vietnamese for the end-users.`;

return [{
  prompt,
  aiReviewId: ctx.aiReviewId,
  callbackUrl: ctx.callbackUrl,
  reviewKind: ctx.reviewKind
}];

