const content = $json.candidates?.[0]?.content?.parts
  ?.map((part) => part.text || '')
  .join('')
  .trim();

if (!content) {
  throw new Error('Gemini response did not contain candidates[0].content.parts[].text');
}

let normalizedContent = content;

// Defensive cleanup in case the model still wraps JSON in markdown fences.
if (normalizedContent.startsWith('```')) {
  normalizedContent = normalizedContent
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();
}

// Validate that Backend receives a JSON string, not a loose object or markdown.
try {
  JSON.parse(normalizedContent);
} catch (error) {
  throw new Error(`Gemini returned malformed JSON: ${error.message}`);
}

const ctx = $('Build Per Push Prompt').item.json;
const usage = $json.usageMetadata || {};

return [{
  aiReviewId: ctx.aiReviewId,
  callbackUrl: ctx.callbackUrl,
  status: 'success',
  rawResponse: normalizedContent,
  modelName: $env.GEMINI_MODEL || 'gemini-2.5-flash',
  provider: 'google-gemini',
  tokenUsage: {
    inputTokens: usage.promptTokenCount || null,
    outputTokens: usage.candidatesTokenCount || null,
    totalTokens: usage.totalTokenCount || null
  }
}];

const ctx = $('Normalize Per Push').item.json;
const message = $json.error?.message || $json.message || $json.body?.message || 'Unknown workflow error';
return [{
  callbackUrl: ctx.callbackUrl,
  status: 'error',
  errorMessage: message
}];

const commits = Array.isArray($input.first().json) ? $input.first().json : [];
const ctx = $('Normalize Aggregate').item.json;
const compactCommits = commits.slice(0, 20).map((commit, index) => {
  const sha = commit.sha || '';
  const message = commit.commit?.message || '';
  const author = commit.commit?.author?.name || 'unknown';
  const date = commit.commit?.author?.date || '';
  return `${index + 1}. SHA: ${sha}
AUTHOR: ${author}
DATE: ${date}
MESSAGE: ${message}`;
}).join('

');

