const crypto = require('crypto');

const input = $input.first().json;

const encrypted =
  input.encryptedGithubToken ||
  input.githubTokenEncrypted;

if (!encrypted) {
  throw new Error('Missing encryptedGithubToken');
}

// Expected format: iv.tag.ciphertext
const parts = encrypted.split('.');

if (parts.length !== 3) {
  throw new Error('Invalid encryptedGithubToken format. Expected: iv.tag.ciphertext');
}

const [ivB64, tagB64, cipherB64] = parts;

const keyB64 = $env.GITHUB_TOKEN_DECRYPTION_KEY;

if (!keyB64) {
  throw new Error('Missing env GITHUB_TOKEN_DECRYPTION_KEY');
}

const key = Buffer.from(keyB64, 'base64');
const iv = Buffer.from(ivB64, 'base64');
const tag = Buffer.from(tagB64, 'base64');
const ciphertext = Buffer.from(cipherB64, 'base64');

if (key.length !== 32) {
  throw new Error('Invalid AES key length. AES-256-GCM requires 32 bytes key.');
}

if (iv.length !== 12) {
  throw new Error('Invalid IV length. AES-GCM should use 12 bytes IV.');
}

const decipher = crypto.createDecipheriv('aes-256-gcm', key, iv);
decipher.setAuthTag(tag);

let githubToken = Buffer.concat([
  decipher.update(ciphertext),
  decipher.final()
]).toString('utf8');

githubToken = githubToken.trim();

if (
  !githubToken.startsWith('ghp_') &&
  !githubToken.startsWith('github_pat_') &&
  !githubToken.startsWith('ghs_')
) {
  throw new Error('Decoded GitHub token format is invalid');
}

return [
  {
    json: {
      ...input,
      githubToken
    }
  }
];

